s=s.replace('<div class="support-reference" data-support="${i}"><span>${F.ITEMS[item.type].name}</span>${supportPattern', '<div class="support-reference" data-kind="${item.type}" data-support="${i}">${supportIcon(item.type)}<span class="support-label">${F.ITEMS[item.type].name}<small>${({bomb:"区域打击",strafe:"线性打击",laser:"追踪打击",emp:"区域压制",barricade:"防御部署",lure:"战术诱导"})[item.type]}</small></span>${supportPattern')
